<template>
    <div><div class="ma-panel">
        <div class="ma-panel-head"><div><h2>App Settings</h2><p class="ma-muted">Release requirements, maintenance, support contacts, and supported app features.</p></div><span v-if="!options.permissions.settings_update" class="ma-badge">View only</span></div>
        <div v-if="loading" class="ma-empty" role="status">Loading app settings…</div>
        <div v-else class="ma-panel-body">
            <div v-if="error" class="ma-error" role="alert">{{ error }} <button type="button" class="btn btn-outline-danger btn-sm ml-2" :disabled="saving" @click="reload">Reload settings</button></div>
            <div v-if="notice" class="ma-error ma-success" role="status">{{ notice }}</div>
            <p v-for="(notice,index) in serverNotices" :key="index" class="ma-note">{{ notice }}</p>
            <form v-if="settings" class="ma-form" @submit.prevent="save">
                <fieldset :disabled="!options.permissions.settings_update || saving"><legend>Versions & Updates</legend><p class="ma-muted mb-3">The mobile app applies the version policy returned by the backend. Set the store links before requiring an update.</p><div class="ma-grid">
                    <div class="ma-field"><label for="ma-latest">Latest app version</label><input id="ma-latest" class="form-control" v-model.trim="settings.latest_version" maxlength="30" required placeholder="1.0.0"></div>
                    <div class="ma-field"><label for="ma-minimum">Minimum supported version</label><input id="ma-minimum" class="form-control" v-model.trim="settings.minimum_supported_version" maxlength="30" required placeholder="1.0.0"></div>
                    <div class="ma-field"><label for="ma-android">Android store URL</label><input id="ma-android" class="form-control" v-model.trim="settings.android_store_url" type="url" pattern="https://.*" maxlength="255" placeholder="https://play.google.com/…"></div>
                    <div class="ma-field"><label for="ma-ios">iOS store URL</label><input id="ma-ios" class="form-control" v-model.trim="settings.ios_store_url" type="url" pattern="https://.*" maxlength="255" placeholder="https://apps.apple.com/…"></div>
                </div><label class="ma-check mt-3"><input type="checkbox" v-model="settings.force_update"><span>Require app update<small>Passengers must update when the server's version policy applies. Both platform store links are required.</small></span></label></fieldset>
                <fieldset :disabled="!options.permissions.settings_update || saving"><legend>Maintenance</legend><label class="ma-check mb-3"><input type="checkbox" v-model="settings.maintenance_mode"><span>Enable maintenance mode<small>Publish the maintenance notice through the mobile configuration.</small></span></label><div class="ma-field"><label for="ma-maintenance">Maintenance message</label><textarea id="ma-maintenance" class="form-control" v-model.trim="settings.maintenance_message" rows="3" maxlength="5000" :required="settings.maintenance_mode" placeholder="Explain the interruption and when to try again."></textarea></div></fieldset>
                <fieldset :disabled="!options.permissions.settings_update || saving"><legend>Passenger Support</legend><div class="ma-grid"><div class="ma-field"><label for="ma-support-phone">Support phone</label><input id="ma-support-phone" class="form-control" v-model.trim="settings.support_phone" type="tel" maxlength="50"></div><div class="ma-field"><label for="ma-support-whatsapp">WhatsApp number</label><input id="ma-support-whatsapp" class="form-control" v-model.trim="settings.support_whatsapp" type="tel" maxlength="50"></div><div class="ma-field"><label for="ma-support-email">Support email</label><input id="ma-support-email" class="form-control" v-model.trim="settings.support_email" type="email" maxlength="255"></div></div></fieldset>
                <fieldset><legend>Feature Availability</legend><label class="ma-check mb-3"><input type="checkbox" v-model="settings.features.wallet" :disabled="!options.permissions.settings_update || saving"><span>Wallet feature<small>The existing backend remains responsible for wallet eligibility, balances, and transactions.</small></span></label><div class="ma-grid"><div><h3>Online payments</h3><span class="ma-badge" :class="settings.features.online_payments === true ? 'active' : ''">{{ settings.features.online_payments === null ? 'Managed on mobile server' : settings.features.online_payments ? 'Available' : 'Unavailable' }}</span><p class="ma-muted mt-2">Live gateway availability cannot be verified from the ERP host.</p></div><div><h3>Payment methods</h3><span class="ma-badge" v-for="method in settings.payment_methods || []" :key="method" style="margin:0 5px 5px 0">{{ label(method) }}</span><p class="ma-muted mt-2">Configured checkout methods are shown for reference. Merchant credentials are managed on the server.</p></div><div><label class="ma-check"><input type="checkbox" v-model="settings.features.notifications" :disabled="!options.permissions.settings_update || saving"><span>Passenger notifications<small>Enable the inbox, automatic booking alerts, and announcements. Phone push also requires delivery setup and passenger permission.</small></span></label></div><div><h3>Promotions</h3><span class="ma-badge disabled">Unavailable</span><p class="ma-muted mt-2">Promotion support is not enabled by the mobile backend.</p></div></div></fieldset>
                <div v-if="options.permissions.settings_update" class="ma-settings-footer"><div class="ma-field mb-3"><label for="ma-settings-reason">Reason for this change</label><input id="ma-settings-reason" class="form-control" v-model.trim="reason" minlength="3" maxlength="1000" required :disabled="saving" placeholder="Explain the release, maintenance or support update"></div><div class="ma-actions"><p class="ma-muted">All changes are audited. A newer configuration must be reloaded before saving.</p><button class="btn btn-success" :disabled="saving || !dirty || reason.length < 3">{{ saving ? 'Saving settings…' : 'Save app settings' }}</button></div></div>
            </form>
        </div>
    </div><AppControls ref="appControls" :options="options" /></div>
</template>
<script>
import AppControls from './AppControls.vue';
import { request, label } from './mobileApp';
const editable = ['latest_version','minimum_supported_version','force_update','maintenance_mode','maintenance_message','android_store_url','ios_store_url','support_phone','support_whatsapp','support_email'];
export default {
    components:{AppControls},props:{options:Object},data:()=>({settings:null,revision:'',baseline:'',reason:'',loading:false,saving:false,error:'',notice:'',sequence:0,serverNotices:[]}),
    computed:{dirty(){return !!this.settings && JSON.stringify(this.payload())!==this.baseline;}},mounted(){this.load();},beforeUnmount(){this.sequence++;},
    methods:{label,payload(){return {...Object.fromEntries(editable.map(key=>[key,this.settings[key]===undefined||this.settings[key]===''?null:this.settings[key]])),features:{wallet:!!this.settings.features.wallet,notifications:!!this.settings.features.notifications}};},confirmLeave(){return (!this.$refs?.appControls || this.$refs.appControls.confirmLeave())&&!this.saving&&(!this.dirty||window.confirm('Leave without saving the app settings?'));},async reload(){if(this.dirty&&!window.confirm('Reload settings and discard your unsaved edits?'))return;await this.load();},async load(){const sequence=++this.sequence;this.loading=true;this.error='';try{const data=await request(this,'get','settings');if(sequence!==this.sequence)return;this.serverNotices=data.notices||[];this.settings={...data.settings,features:{...data.settings.features}};this.settings.force_update=!!this.settings.force_update;this.settings.maintenance_mode=!!this.settings.maintenance_mode;this.settings.features.wallet=!!this.settings.features.wallet;this.revision=data.revision;this.baseline=JSON.stringify(this.payload());this.reason='';}catch(error){if(sequence===this.sequence)this.error=error.message;}finally{if(sequence===this.sequence)this.loading=false;}},async save(){if(this.saving||!this.dirty||this.reason.length<3)return;this.saving=true;this.error='';this.notice='';try{await request(this,'put','settings',{settings:this.payload(),revision:this.revision,reason:this.reason});this.notice='App settings saved.';await this.load();}catch(error){this.error=error.message;}finally{this.saving=false;}},},
};
</script>
